script:
export const meta = {
  name: 'reauthor-merge-pdfs',
  description: 'Re-author each task\'s broken stub merge/press PDF as a real press-PDF HTML: task\'s actual field values, a genuinely PLACED photo, the structural trap, correct trim (no bleed) — to be Chrome-printed into a real convert_pdf_to_indd-ready PDF',
  phases: [{ title: 'Author PDF HTML' }],
}
const BASE = '/Users/dhiren/Downloads/Deccan/Adobe-Freelance-Leads'
const IDS = args

const SCHEMA = {
  type: 'object',
  properties: {
    task_id: { type: 'string' },
    pdfs: {
      type: 'array',
      items: {
        type: 'object',
        properties: {
          pdf_filename: { type: 'string' },
          html_written: { type: 'boolean' },
          placed_image_file: { type: 'string' },
          trap_baked: { type: 'string' },
          real_fields_used: { type: 'boolean' },
        },
        required: ['pdf_filename', 'html_written', 'placed_image_file'],
      },
    },
    bleed_overclaim_in_spec: { type: 'boolean' },
    summary: { type: 'string' },
  },
  required: ['task_id', 'pdfs', 'bleed_overclaim_in_spec', 'summary'],
}

const results = await parallel(IDS.map((id) => () => agent(
  `Re-author the broken stub press/merge PDF(s) for task ${id} as REAL press-PDF HTML. The current PDFs are placeholder stubs ("The Vesper / [PIECE IMAGE]", no placed image, non-embedded fonts) that break convert_pdf_to_indd. You will write faithful HTML; a central step Chrome-prints it to a real PDF.\n\n` +
  `READ:\n` +
  `- ${BASE}/input_assets_v3/${id}/asset_plan.json — find every asset with "type":"pdf". Its "content" field is the LAYOUT SPEC (trim size in mm, the printed blocks, fonts, hex colours, and the reverse-engineering TRAP).\n` +
  `- ${BASE}/complex_benchmark/adobe_only/specs_v3/${id}.json — brand_identity (real palette hex, brand name) and the emergent_checkpoints the PDF must trigger.\n` +
  `- The task's CSV asset in ${BASE}/input_assets_v3/${id}/assets/ (if any) — use a REAL representative record's actual values (item name, size, price, allergens, etc.), NEVER "The Vesper".\n` +
  `- List ${BASE}/input_assets_v3/${id}/assets/ and pick ONE existing photoreal image that this card would show (a dish / product / piece / room / listing photo — NOT a logo, wordmark, csv, txt or the stub pdf).\n\n` +
  `For EACH pdf asset, WRITE ${BASE}/input_assets_v3/${id}/pdfsrc/<pdf-basename>.html (create the pdfsrc dir) as a SELF-CONTAINED single-record press card:\n` +
  `- <style>@page{size:<W>mm <H>mm;margin:0} html,body{margin:0}</style> where W×H is the spec's exact trim in mm. NO bleed (media box = trim). One card div exactly <W>mm × <H>mm.\n` +
  `- Show ONE real record using the task's ACTUAL field values from the CSV/spec (real item name, price, size, allergens/provenance, code — whatever fields the layout spec lists).\n` +
  `- PLACE the chosen photo with a real <img src="file://${BASE}/input_assets_v3/${id}/assets/<file>" ...> sized to the picture area the layout describes. This placed image is MANDATORY (convert_pdf_to_indd needs a real graphic frame).\n` +
  `- BAKE THE STRUCTURAL TRAP exactly as the layout spec's "how it is actually set" describes: if name/size/price are "one continuous story / single text frame", put them in ONE text block (not separate divs per field); if there is a decorative price ROUNDEL/sunburst that only LOOKS like a picture well, draw it as an inline <svg> or CSS radial shape (NOT an <img>); bake any stale/wrong value the spec calls for; keep media box = trim (no bleed box).\n` +
  `- Use a real font stack matching the brand voice (a serif like Georgia/'Times New Roman', or a sans like Arial/Helvetica); Chrome will embed subsets. Use the brand palette hex for grounds/ink.\n` +
  `Keep it a faithful, plausible printer's proof — realistic, not decorative filler.\n\n` +
  `Then report: for each pdf, the pdf_filename (exact name from the plan), html_written, the placed_image_file you used, and one line naming the trap you baked. Set bleed_overclaim_in_spec=true if the spec's deliverables/trajectory/doability_proof claim 3mm bleed or "press-ready with bleed" from this PDF-derived template (which the connector cannot produce) — do NOT edit the spec, just flag it. Do not touch any file other than the HTML(s) you write.`,
  { agentType: 'general-purpose', phase: 'Author PDF HTML', label: `pdf:${id}`, schema: SCHEMA }
)))

const r = results.filter(Boolean)
return {
  tasks: r.length,
  htmls_written: r.reduce((s, x) => s + (x.pdfs || []).filter(p => p.html_written).length, 0),
  all_placed_image: r.every(x => (x.pdfs || []).every(p => p.placed_image_file)),
  bleed_overclaim_tasks: r.filter(x => x.bleed_overclaim_in_spec).map(x => x.task_id),
  per_task: r.map(x => ({ id: x.task_id, n: (x.pdfs || []).length })),
}
